{"summary":"Create erasure-repository.ts","path":"/workspace/source/apps/customer-service/src/erasure-repository.ts","file_text":"import type pg from 'pg';
import { pool } from '../../../packages/database/src/pool.js';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  max_attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export function formatErasureRequest(row: ErasureRequestRow): {
  id: string;
  customerId: string;
  status: string;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
} {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error ?? null,
  };
}

export class ErasureRepository {
  async findByCustomer(client: pg.PoolClient | typeof pool, merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findById(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id = $1 AND id = $2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async create(client: pg.PoolClient, merchantId: string, customerId: string): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id, customer_id, status, attempts)
       VALUES($1, $2, 'pending', 0)
       RETURNING *`,
      [merchantId, customerId],
    );
    return result.rows[0]!;
  }

  async resetFailed(client: pg.PoolClient, id: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status = 'pending', last_error = NULL, updated_at = now()
       WHERE id = $1 AND status = 'failed'
       RETURNING *`,
      [id],
    );
    return result.rows[0];
  }

  async claimPending(client: pg.PoolClient, id: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status = 'processing', attempts = attempts + 1, updated_at = now()
       WHERE id = $1 AND status IN ('pending', 'failed')
       RETURNING *`,
      [id],
    );
    return result.rows[0];
  }

  async listPending(limit = 10): Promise<ErasureRequestRow[]> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests
       WHERE status = 'pending'
       ORDER BY created_at ASC
       LIMIT $1`,
      [limit],
    );
    return result.rows;
  }

  async markCompleted(client: pg.PoolClient, id: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status = 'completed', completed_at = now(), updated_at = now(), last_error = NULL
       WHERE id = $1`,
      [id],
    );
  }

  async markFailed(id: string, errorCode: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status = 'failed', last_error = $2, updated_at = now()
       WHERE id = $1`,
      [id, errorCode],
    );
  }
}
