import { v4 as uuid } from 'uuid';
import { Redis } from 'ioredis';
import { config } from '../../../packages/config/src/index.js';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, ensureBucket, objectStore } from '../../../packages/storage/src/minio.js';
import {
  ErasureRepository,
  formatErasureRequest,
  type ErasureRequestRow,
} from './erasure-repository.js';

function requestHash(value: unknown): string {
  return createHash('sha256').update(JSON.stringify(value)).digest('hex');
}

function isNotFoundError(error: unknown): boolean {
  if (typeof error === 'object' && error !== null) {
    const err = error as {
      statusCode?: unknown;
      meta?: { statusCode?: unknown };
      body?: { result?: unknown; found?: unknown };
    };
    if (err.statusCode === 404 || err.meta?.statusCode === 404) return true;
    if (err.body?.result === 'not_found' || err.body?.found === false) return true;
  }
  return false;
}

export class CustomerErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  async createOrGet(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<{ status: number; body: Record<string, unknown> }> {
    const hash = requestHash({ customerId });
    const result = await transaction(async (client) => {
      // 1. Check if customer exists in customers.customers or erasure_requests
      const customerExists = await client.query(
        `SELECT 1 FROM customers.customers WHERE merchant_id = $1 AND id = $2`,
        [merchantId, customerId],
      );
      const existingErasure = await this.repository.findByCustomer(client, merchantId, customerId);

      if (!customerExists.rowCount && !existingErasure) {
        throw Object.assign(new Error('customer not found'), { statusCode: 404 });
      }

      // 2. Check / reserve idempotency key
      const inserted = await client.query(
        `INSERT INTO operations.idempotency_keys(merchant_id, scope, key, request_hash, expires_at)
         VALUES($1, 'customer-erasure', $2, $3, now() + interval '24 hours')
         ON CONFLICT DO NOTHING`,
        [merchantId, idempotencyKey, hash],
      );

      if (!inserted.rowCount) {
        const existingKey = await client.query<{
          request_hash: string;
          response_status: number | null;
          response_body: unknown;
        }>(
          `SELECT request_hash, response_status, response_body
           FROM operations.idempotency_keys
           WHERE merchant_id = $1 AND scope = 'customer-erasure' AND key = $2
           FOR UPDATE`,
          [merchantId, idempotencyKey],
        );
        const row = existingKey.rows[0];
        if (!row || row.request_hash !== hash) {
          throw Object.assign(new Error('idempotency key reused with different request'), { statusCode: 409 });
        }
      }

      // 3. Handle existing erasure request vs new erasure request
      let erasureRow: ErasureRequestRow;
      if (existingErasure) {
        if (existingErasure.status === 'failed') {
          const reset = await this.repository.resetFailed(client, existingErasure.id);
          erasureRow = reset ?? existingErasure;
        } else {
          erasureRow = existingErasure;
        }
      } else {
        erasureRow = await this.repository.create(client, merchantId, customerId);
      }

      const body = formatErasureRequest(erasureRow);
      await client.query(
        `UPDATE operations.idempotency_keys
         SET response_status = $4, response_body = $5
         WHERE merchant_id = $1 AND scope = 'customer-erasure' AND key = $2`,
        [merchantId, idempotencyKey, 202, body],
      );

      return { row: erasureRow, body };
    });

    if (result.row.status === 'pending') {
      setImmediate(() => {
        void this.processErasure(result.row.id).catch((err) => {
          logger.error({ err, requestId: result.row.id }, 'async erasure execution failed');
        });
      });
    }

    return { status: 202, body: result.body };
  }

  async get(merchantId: string, requestId: string): Promise<Record<string, unknown> | undefined> {
    const row = await this.repository.findById(merchantId, requestId);
    if (!row) return undefined;
    return formatErasureRequest(row);
  }

  async processErasure(requestId: string): Promise<void> {
    const claimed = await transaction(async (client) => {
      return await this.repository.claimPending(client, requestId);
    });
    if (!claimed) return;

    const { merchant_id: merchantId, customer_id: customerId } = claimed;

    try {
      // 1. Gather all emails for this customer before deleting SQL records
      const emails = await this.collectCustomerEmails(merchantId, customerId);

      // 2. Clean up Mailpit messages
      for (const email of emails) {
        try {
          await deleteMailpitMessagesForRecipient(email);
        } catch (err) {
          logger.warn({ err, email }, 'failed to delete mailpit messages for recipient');
        }
      }

      // 3. Clean up Redis projections & activity cache
      try {
        const redis = new Redis(config().REDIS_URL);
        await redis.del(`merchant:${merchantId}:customer:${customerId}`);
        await redis.del(`merchant:${merchantId}:customer:${customerId}:activity`);
        await redis.quit();
      } catch (err) {
        logger.warn({ err, customerId }, 'failed to clean up redis customer projection');
      }

      // 4. Clean up OpenSearch
      try {
        await searchClient.delete({
          index: CUSTOMER_INDEX,
          id: `${merchantId}:${customerId}`,
        });
      } catch (err: unknown) {
        if (!isNotFoundError(err)) {
          logger.warn({ err, customerId }, 'failed to delete opensearch customer document');
        }
      }

      // 5. Clean up & sanitize MinIO objects
      await this.sanitizeMinioObjects(merchantId, customerId);

      // 6. Clean up database records in a transaction
      await transaction(async (client) => {
        // provider_sandbox.customers
        await client.query(
          `DELETE FROM provider_sandbox.customers WHERE merchant_id = $1 AND payflow_customer_id = $2`,
          [merchantId, customerId],
        );

        // customers.provider_customer_mappings
        await client.query(
          `DELETE FROM customers.provider_customer_mappings WHERE merchant_id = $1 AND customer_id = $2`,
          [merchantId, customerId],
        );

        // customers.payment_method_refs
        await client.query(
          `DELETE FROM customers.payment_method_refs WHERE merchant_id = $1 AND customer_id = $2`,
          [merchantId, customerId],
        );

        // customers.addresses
        await client.query(
          `DELETE FROM customers.addresses WHERE merchant_id = $1 AND customer_id = $2`,
          [merchantId, customerId],
        );

        // customers.contacts
        await client.query(
          `DELETE FROM customers.contacts WHERE merchant_id = $1 AND customer_id = $2`,
          [merchantId, customerId],
        );

        // customers.support_participants & support_messages & support_tickets
        await client.query(
          `DELETE FROM customers.support_participants WHERE customer_id = $1`,
          [customerId],
        );
        await client.query(
          `UPDATE customers.support_messages SET body = '[deleted]', attachments = '[]'::jsonb
           WHERE merchant_id = $1 AND author_id = $2`,
          [merchantId, customerId],
        );
        await client.query(
          `DELETE FROM customers.support_messages WHERE ticket_id IN (
             SELECT id FROM customers.support_tickets st WHERE st.merchant_id = $1
             AND NOT EXISTS (SELECT 1 FROM customers.support_participants sp WHERE sp.ticket_id = st.id)
           )`,
          [merchantId],
        );
        await client.query(
          `DELETE FROM customers.support_tickets st WHERE st.merchant_id = $1
           AND NOT EXISTS (SELECT 1 FROM customers.support_participants sp WHERE sp.ticket_id = st.id)`,
          [merchantId],
        );

        // operations.notification_preferences
        await client.query(
          `DELETE FROM operations.notification_preferences WHERE merchant_id = $1 AND customer_id = $2`,
          [merchantId, customerId],
        );

        // operations.notifications
        await client.query(
          `DELETE FROM operations.notifications WHERE merchant_id = $1 AND customer_id = $2`,
          [merchantId, customerId],
        );

        // operations.email_deliveries
        await client.query(
          `DELETE FROM operations.email_deliveries WHERE merchant_id = $1 AND customer_id = $2`,
          [merchantId, customerId],
        );

        // operations.analytics_events
        await client.query(
          `DELETE FROM operations.analytics_events WHERE merchant_id = $1 AND customer_id = $2`,
          [merchantId, customerId],
        );

        // operations.jobs
        await client.query(
          `DELETE FROM operations.jobs WHERE merchant_id = $1 AND payload->>'customerId' = $2::text`,
          [merchantId, customerId],
        );

        // payments.payment_intents (sanitize customer_snapshot)
        await client.query(
          `UPDATE payments.payment_intents
           SET customer_snapshot = jsonb_build_object('id', customer_id, 'redacted', true), updated_at = now()
           WHERE merchant_id = $1 AND customer_id = $2`,
          [merchantId, customerId],
        );

        // payments.refunds (clear customer_email)
        await client.query(
          `UPDATE payments.refunds
           SET customer_email = NULL
           WHERE merchant_id = $1 AND payment_intent_id IN (
             SELECT id FROM payments.payment_intents WHERE customer_id = $2
           )`,
          [merchantId, customerId],
        );

        // payments.invoices (sanitize billing_snapshot)
        await client.query(
          `UPDATE payments.invoices
           SET billing_snapshot = jsonb_build_object('id', customer_id, 'redacted', true)
           WHERE merchant_id = $1 AND customer_id = $2`,
          [merchantId, customerId],
        );

        // customers.customers (delete record)
        await client.query(
          `DELETE FROM customers.customers WHERE merchant_id = $1 AND id = $2`,
          [merchantId, customerId],
        );

        // platform.audit_logs (sanitize metadata of past logs and add customer.erased log)
        await client.query(
          `UPDATE platform.audit_logs SET metadata = '{}'::jsonb WHERE merchant_id = $1 AND target_id = $2::text`,
          [merchantId, customerId],
        );
        await client.query(
          `INSERT INTO platform.audit_logs(merchant_id, actor_type, target_type, target_id, action, metadata, correlation_id)
           VALUES($1, 'api_key', 'customer', $2, 'customer.erased', '{}'::jsonb, gen_random_uuid())`,
          [merchantId, customerId],
        );

        // Outbox event: EVENT_TYPES.CUSTOMER_ERASED
        await addOutboxEvent(client, {
          eventType: EVENT_TYPES.CUSTOMER_ERASED,
          aggregateType: 'customer',
          aggregateId: customerId,
          merchantId,
          correlationId: uuid(),
          payload: { customerId },
        });

        // Mark erasure request completed
        await this.repository.markCompleted(client, requestId);
      });
    } catch (error) {
      logger.error({ error, requestId, customerId }, 'customer erasure processing failed');
      const errorCode = 'erasure_cleanup_failed';
      await this.repository.markFailed(requestId, errorCode);
    }
  }

  async startWorker(signal: AbortSignal): Promise<void> {
    while (!signal.aborted) {
      try {
        const pending = await this.repository.listPending(5);
        for (const req of pending) {
          if (signal.aborted) break;
          await this.processErasure(req.id);
        }
      } catch (err) {
        logger.error({ err }, 'erasure worker poll failed');
      }
      await new Promise((resolve) => setTimeout(resolve, 500));
    }
  }

  private async collectCustomerEmails(merchantId: string, customerId: string): Promise<string[]> {
    const emails = new Set<string>();

    const cRes = await pool.query<{ email: string }>(
      `SELECT email FROM customers.customers WHERE merchant_id = $1 AND id = $2`,
      [merchantId, customerId],
    );
    if (cRes.rows[0]?.email) emails.add(cRes.rows[0].email);

    const contacts = await pool.query<{ value: string }>(
      `SELECT value FROM customers.contacts WHERE merchant_id = $1 AND customer_id = $2 AND kind = 'email'`,
      [merchantId, customerId],
    );
    for (const row of contacts.rows) {
      if (row.value) emails.add(row.value);
    }

    const delivs = await pool.query<{ destination: string }>(
      `SELECT destination FROM operations.email_deliveries WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );
    for (const row of delivs.rows) {
      if (row.destination) emails.add(row.destination);
    }

    const prefs = await pool.query<{ destination: string }>(
      `SELECT destination FROM operations.notification_preferences WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );
    for (const row of prefs.rows) {
      if (row.destination) emails.add(row.destination);
    }

    const refunds = await pool.query<{ customer_email: string }>(
      `SELECT customer_email FROM payments.refunds
       WHERE merchant_id = $1 AND customer_email IS NOT NULL AND payment_intent_id IN (
         SELECT id FROM payments.payment_intents WHERE customer_id = $2
       )`,
      [merchantId, customerId],
    );
    for (const row of refunds.rows) {
      if (row.customer_email) emails.add(row.customer_email);
    }

    return [...emails];
  }

  private async sanitizeMinioObjects(merchantId: string, customerId: string): Promise<void> {
    await ensureBucket();

    // 1. Customer imports
    const imports = await pool.query<{ object_key: string; import_id: string }>(
      `SELECT d.object_key, c.id AS import_id
       FROM operations.document_manifests d
       LEFT JOIN customers.customer_imports c ON c.object_key = d.object_key
       WHERE d.merchant_id = $1 AND (d.customer_id = $2 OR d.metadata->>'customerId' = $2::text)
       AND d.document_type = 'customer_import'`,
      [merchantId, customerId],
    );
    for (const imp of imports.rows) {
      try {
        await objectStore.removeObject(DOCUMENT_BUCKET, imp.object_key);
      } catch { /* ignore */ }
      await pool.query(`DELETE FROM operations.document_manifests WHERE object_key = $1`, [imp.object_key]);
      if (imp.import_id) {
        await pool.query(`DELETE FROM customers.customer_imports WHERE id = $1`, [imp.import_id]);
      }
    }

    const allImports = await pool.query<{ object_key: string; id: string }>(
      `SELECT c.object_key, c.id FROM customers.customer_imports c
       WHERE c.merchant_id = $1`,
      [merchantId],
    );
    for (const imp of allImports.rows) {
      try {
        const stream = await objectStore.getObject(DOCUMENT_BUCKET, imp.object_key);
        const chunks: Buffer[] = [];
        for await (const chunk of stream) {
          chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
        }
        const raw = Buffer.concat(chunks).toString('utf8');
        if (raw.includes(customerId)) {
          await objectStore.removeObject(DOCUMENT_BUCKET, imp.object_key);
          await pool.query(`DELETE FROM operations.document_manifests WHERE object_key = $1`, [imp.object_key]);
          await pool.query(`DELETE FROM customers.customer_imports WHERE id = $1`, [imp.id]);
        }
      } catch { /* ignore */ }
    }

    // 2. Receipts
    const receipts = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests
       WHERE merchant_id = $1 AND customer_id = $2 AND document_type = 'receipt'`,
      [merchantId, customerId],
    );
    for (const r of receipts.rows) {
      try {
        const stream = await objectStore.getObject(DOCUMENT_BUCKET, r.object_key);
        const chunks: Buffer[] = [];
        for await (const chunk of stream) {
          chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
        }
        const raw = Buffer.concat(chunks).toString('utf8');
        const data = JSON.parse(raw) as { customer?: unknown };
        data.customer = { id: customerId, redacted: true };
        const updated = JSON.stringify(data);
        const checksum = createHash('sha256').update(updated).digest('hex');
        await objectStore.putObject(DOCUMENT_BUCKET, r.object_key, updated, Buffer.byteLength(updated), {
          'Content-Type': 'application/json',
        });
        await pool.query(
          `UPDATE operations.document_manifests SET checksum = $1 WHERE object_key = $2`,
          [checksum, r.object_key],
        );
      } catch { /* ignore */ }
    }

    // 3. Invoices
    const invoices = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM payments.invoices
