test('erasure request contract schema validates status and properties', () => {
  const req = {
    id: randomUUID(),
    customerId: randomUUID(),
    status: 'pending' as const,
    attempts: 0,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    completedAt: null,
    lastError: null,
  };

  const parsed = erasureRequestSchema.parse(req);
  assert.equal(parsed.id, req.id);
  assert.equal(parsed.status, 'pending');
  assert.equal(parsed.completedAt, null);
  assert.equal(parsed.lastError, null);

  const completed = erasureRequestSchema.parse({
    ...req,
    status: 'completed',
    attempts: 1,
    completedAt: new Date().toISOString(),
  });
  assert.equal(completed.status, 'completed');
  assert.ok(completed.completedAt);

  const failed = erasureRequestSchema.parse({
    ...req,
    status: 'failed',
    attempts: 2,
    lastError: 'storage_cleanup_failed',
  });
  assert.equal(failed.status, 'failed');
  assert.equal(failed.lastError, 'storage_cleanup_failed');

  assert.throws(() => erasureRequestSchema.parse({ ...req, status: 'unknown_status' }));
  assert.throws(() => erasureRequestSchema.parse({ ...req, id: 'not-a-uuid' }));
});

test('domain event types include customer.erased.v1', () => {
  assert.equal(EVENT_TYPES.CUSTOMER_ERASED, 'customer.erased.v1');
});
"}

