    'POST',
    undefined,
    404,
    { 'idempotency-key': 'valid-key-tenant2' },
    secondApiKey,
  );

  // Submit valid erasure request with idempotency key
  const eraseKey1 = `erase-key-1-${runSuffix}`;
  const eraseRes1 = (
    await api<ErasureResponse>(
      `/v1/customers/${customer.id}/erasure-requests`,
      'POST',
      undefined,
      202,
      { 'idempotency-key': eraseKey1 },
    )
  ).data;

  assert.equal(eraseRes1.customerId, customer.id);
  assert.ok(eraseRes1.id);
  assert.ok(eraseRes1.status === 'pending' || eraseRes1.status === 'processing' || eraseRes1.status === 'completed');

  // Reusing same idempotency key for same customer returns the same request
  const replayRes = (
    await api<ErasureResponse>(
      `/v1/customers/${customer.id}/erasure-requests`,
      'POST',
      undefined,
      202,
      { 'idempotency-key': eraseKey1 },
    )
  ).data;
  assert.equal(replayRes.id, eraseRes1.id);

  // Reusing same idempotency key for a DIFFERENT customer returns 409 Conflict
  const otherCustomer = (
    await api<{ id: string }>(
      '/v1/customers',
      'POST',
      {
        externalReference: `other-${runSuffix}`,
        email: `other-${runSuffix}@example.test`,
        name: 'Other User',
      },
      201,
    )
  ).data;

  await api(
    `/v1/customers/${otherCustomer.id}/erasure-requests`,
    'POST',
    undefined,
    409,
    { 'idempotency-key': eraseKey1 },
  );

  // A new idempotency key for the same customer returns that existing request
  const eraseKey2 = `erase-key-2-${runSuffix}`;
  const existingRes = (
    await api<ErasureResponse>(
      `/v1/customers/${customer.id}/erasure-requests`,
      'POST',
      undefined,
      202,
      { 'idempotency-key': eraseKey2 },
    )
  ).data;
  assert.equal(existingRes.id, eraseRes1.id);

  console.log('--- Step 3: Wait for Erasure Request to Complete ---');
  const finalErasure = await waitForErasure(eraseRes1.id);
  assert.equal(finalErasure.status, 'completed', 'Erasure request should be completed');
  assert.ok(finalErasure.completedAt, 'completedAt must be set');
  assert.equal(finalErasure.lastError, null, 'lastError must be null');

  // Test checking request with GET /v1/erasure-requests/:requestId
  const checkRes = (await api<ErasureResponse>(`/v1/erasure-requests/${eraseRes1.id}`)).data;
  assert.equal(checkRes.id, eraseRes1.id);
  assert.equal(checkRes.status, 'completed');

  // Merchant 2 cannot check status of Merchant 1's erasure request
  await api(
    `/v1/erasure-requests/${eraseRes1.id}`,
    'GET',
    undefined,
    404,
    {},
    secondApiKey,
  );

  console.log('--- Step 4: Verify Personal Data Deletion and Anonymization ---');

  // 1. GET /v1/customers/:id returns 404
  await api(`/v1/customers/${customer.id}`, 'GET', undefined, 404);

  // 2. GET /v1/customers does not list erased customer
  const listRes = (await api<{ data: Array<{ id: string }> }>('/v1/customers')).data;
  assert.ok(!listRes.data.some((c) => c.id === customer.id), 'Erased customer must not appear in customer list');

  // 3. Redis keys are deleted
  const redisAfter = await redis.get(redisKey);
  assert.equal(redisAfter, null, 'Customer Redis projection should be deleted');
  const redisActivity = await redis.hgetall(`${redisKey}:activity`);
  assert.deepEqual(redisActivity, {}, 'Customer Redis activity should be deleted');

  // 4. OpenSearch document is deleted
  const osAfter = await searchClient.exists({ index: CUSTOMER_INDEX, id: `${merchantId}:${customer.id}` });
  assert.equal(osAfter.body, false, 'Customer OpenSearch document should be deleted');

  // 5. Database tables check
  const dbCheck = await pool.query<{
    customers_count: string;
    addresses_count: string;
    contacts_count: string;
    methods_count: string;
    provider_mappings_count: string;
    sandbox_customers_count: string;
    notification_prefs_count: string;
    notifications_count: string;
    email_deliveries_count: string;
    analytics_count: string;
  }>(`
    SELECT
      (SELECT count(*) FROM customers.customers WHERE id = $1)::text AS customers_count,
      (SELECT count(*) FROM customers.addresses WHERE customer_id = $1)::text AS addresses_count,
      (SELECT count(*) FROM customers.contacts WHERE customer_id = $1)::text AS contacts_count,
      (SELECT count(*) FROM customers.payment_method_refs WHERE customer_id = $1)::text AS methods_count,
      (SELECT count(*) FROM customers.provider_customer_mappings WHERE customer_id = $1)::text AS provider_mappings_count,
      (SELECT count(*) FROM provider_sandbox.customers WHERE payflow_customer_id = $1)::text AS sandbox_customers_count,
      (SELECT count(*) FROM operations.notification_preferences WHERE customer_id = $1)::text AS notification_prefs_count,
      (SELECT count(*) FROM operations.notifications WHERE customer_id = $1)::text AS notifications_count,
      (SELECT count(*) FROM operations.email_deliveries WHERE customer_id = $1)::text AS email_deliveries_count,
      (SELECT count(*) FROM operations.analytics_events WHERE customer_id = $1)::text AS analytics_count
  `, [customer.id]);

  const counts = dbCheck.rows[0]!;
  assert.equal(Number(counts.customers_count), 0, 'customers.customers record must be deleted');
  assert.equal(Number(counts.addresses_count), 0, 'customers.addresses must be deleted');
  assert.equal(Number(counts.contacts_count), 0, 'customers.contacts must be deleted');
  assert.equal(Number(counts.methods_count), 0, 'customers.payment_method_refs must be deleted');
  assert.equal(Number(counts.provider_mappings_count), 0, 'customers.provider_customer_mappings must be deleted');
  assert.equal(Number(counts.sandbox_customers_count), 0, 'provider_sandbox.customers must be deleted');
  assert.equal(Number(counts.notification_prefs_count), 0, 'operations.notification_preferences must be deleted');
  assert.equal(Number(counts.notifications_count), 0, 'operations.notifications must be deleted');
  assert.equal(Number(counts.email_deliveries_count), 0, 'operations.email_deliveries must be deleted');
  assert.equal(Number(counts.analytics_count), 0, 'operations.analytics_events must be deleted');

  console.log('--- Step 5: Verify Financial Data Retention ---');

  // 1. Payment intent is retained, but customer_snapshot is redacted
  const piRes = await pool.query<{ id: string; customer_snapshot: Record<string, unknown> }>(
    `SELECT id, customer_snapshot FROM payments.payment_intents WHERE id = $1`,
    [payment.id],
  );
  assert.equal(piRes.rows.length, 1, 'Payment intent must be retained');
  assert.equal(piRes.rows[0]!.customer_snapshot.redacted, true, 'Customer snapshot must be redacted');
  assert.equal((piRes.rows[0]!.customer_snapshot as any).email, undefined, 'Email must not exist in snapshot');
  assert.equal((piRes.rows[0]!.customer_snapshot as any).name, undefined, 'Name must not exist in snapshot');

  // 2. Invoice is retained, billing_snapshot is redacted
  const invRes = await pool.query<{ id: string; billing_snapshot: Record<string, unknown>; object_key: string }>(
    `SELECT id, billing_snapshot, object_key FROM payments.invoices WHERE id = $1`,
    [invoice.id],
  );
  assert.equal(invRes.rows.length, 1, 'Invoice must be retained');
  assert.equal(invRes.rows[0]!.billing_snapshot.redacted, true, 'Billing snapshot must be redacted');

  // 3. Invoice JSON in MinIO has customer redacted
  const invStream = await objectStore.getObject(DOCUMENT_BUCKET, invRes.rows[0]!.object_key);
  const invChunks: Buffer[] = [];
  for await (const chunk of invStream) {
    invChunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
  }
  const invFile = JSON.parse(Buffer.concat(invChunks).toString('utf8'));
  assert.equal(invFile.customer.redacted, true, 'MinIO invoice document customer must be redacted');
  assert.equal(invFile.customer.email, undefined, 'MinIO invoice customer email must be removed');

  // 4. Receipt in MinIO has customer redacted
  const rcptRes = await pool.query<{ object_key: string }>(
    `SELECT object_key FROM operations.document_manifests WHERE metadata->>'paymentId' = $1 AND document_type = 'receipt'`,
    [payment.id],
  );
  assert.equal(rcptRes.rows.length, 1, 'Receipt manifest must be retained');
  const rcptStream = await objectStore.getObject(DOCUMENT_BUCKET, rcptRes.rows[0]!.object_key);
  const rcptChunks: Buffer[] = [];
  for await (const chunk of rcptStream) {
    rcptChunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
  }
  const rcptFile = JSON.parse(Buffer.concat(rcptChunks).toString('utf8'));
  assert.equal(rcptFile.customer.redacted, true, 'MinIO receipt document customer must be redacted');

  // 5. Customer import was removed
  const importManifests = await pool.query(
    `SELECT 1 FROM operations.document_manifests WHERE customer_id = $1 AND document_type = 'customer_import'`,
    [customer.id],
  );
  assert.equal(importManifests.rowCount, 0, 'Customer import manifest must be deleted');

  // 6. Ledger entries and postings are balanced and untouched
  const ledgerCheck = await pool.query<{ discrepancy: string }>(`
    SELECT (SELECT count(*) FROM (
      SELECT e.id FROM payments.ledger_entries e JOIN payments.ledger_postings p ON p.entry_id=e.id
      GROUP BY e.id HAVING sum(CASE WHEN p.direction='debit' THEN p.amount ELSE -p.amount END)<>0
    ) invalid)::text AS discrepancy
  `);
  assert.equal(Number(ledgerCheck.rows[0]!.discrepancy), 0, 'Ledger entries must be balanced');

  // 7. Audit log has customer.erased
  const auditRes = await pool.query<{ action: string; metadata: Record<string, unknown> }>(
    `SELECT action, metadata FROM platform.audit_logs WHERE target_id = $1 ORDER BY created_at DESC LIMIT 1`,
    [customer.id],
  );
  assert.equal(auditRes.rows[0]?.action, 'customer.erased', 'Audit log must record customer.erased');

  console.log('--- Step 6: Verify Replay Safety ---');
  // If we simulate an event for this customer, verify it does not restore projection
  const replayRedisKey = `merchant:${merchantId}:customer:${customer.id}`;
  const replayRedis = await redis.get(replayRedisKey);
  assert.equal(replayRedis, null, 'Replayed event must not restore customer in Redis');

  await redis.quit();
  await pool.end();

  console.log(JSON.stringify({ status: 'success', customerId: customer.id, erasureId: eraseRes1.id }, null, 2));
}

await runTest();
"}

